    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PC0 as Alternate Function AF2 (TIM1_CH1) */
    /* Set MODER0 to 10 (Alternate Function mode) */
    GPIOC->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE0_Pos);

    /* Output type push-pull, high speed, no pull-up / pull-down */
    GPIOC->OTYPER &= ~GPIO_OTYPER_OT0;
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD0_Msk;

    /* Map PC0 to AF2 (AFR[0] / AFRL bits [3:0] = 0b0010) */
    GPIOC->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL0_Pos);
    GPIOC->AFR[0] |= (2U << GPIO_AFRL_AFSEL0_Pos);

    /* 3. Configure TIM1
     * Timer clock = 170 MHz (APB2 prescaler = 1 -> TIM1CLK = PCLK2 = 170 MHz)
     * Target frequency = 20 kHz:
     *   Update frequency = TIM1CLK / ((PSC + 1) * (ARR + 1))
     *   With PSC = 0: ARR + 1 = 170,000,000 / 20,000 = 8500 => ARR = 8499
     * Duty cycle = 25%:
     *   In edge-aligned PWM Mode 1 (up-counting), output is active while CNT < CCR1:
     *   CCR1 = 8500 * 0.25 = 2125
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* Configure PWM mode 1 on Channel 1:
     * OC1M[3:0] = 0b0110 (bits [6:4] = 0b110 in CCMR1, bit 16 = 0)
     * Enable Output Compare 1 Preload (OC1PE)
     */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable output on Channel 1 (CC1E = 1) with active-high polarity (CC1P = 0) */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable Auto-reload Preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* For advanced timer TIM1, enable Main Output Enable (MOE in BDTR) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Generate an update event to transfer preload values into active registers */
    TIM1->EGR = TIM_EGR_UG;

