#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOA and TIM2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM2EN;

    /* 2. Configure PA0 as Alternate Function AF1 (TIM2_CH1) */
    /* Set MODER0 to 0b10 (Alternate Function mode) */
    GPIOA->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE0_Pos);

    /* Output type: Push-Pull */
    GPIOA->OTYPER &= ~GPIO_OTYPER_OT0;

    /* Output speed: Very High Speed */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);

    /* Pull-up / Pull-down: No pull-up, no pull-down */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD0_Msk;

    /* Route AF1 (TIM2_CH1) to PA0 via AFRL register */
    GPIOA->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL0_Pos);
    GPIOA->AFR[0] |= (1U << GPIO_AFRL_AFSEL0_Pos);

    /* 3. Configure TIM2 for 1 kHz PWM with 50 % duty cycle
     * TIM2 kernel clock = PCLK1 = 170 MHz (APB1 prescaler = 1).
     * TIM2 is a 32-bit general-purpose timer.
     * f_PWM = TIM2_CLK / ((PSC + 1) * (ARR + 1))
     * With PSC = 0: ARR = (170,000,000 / 1,000) - 1 = 169999 (exact 1 kHz).
     * Duty cycle = CCR1 / (ARR + 1) = 85000 / 170000 = 50.0 %.
     */
    TIM2->PSC = 0U;
    TIM2->ARR = 169999U;
    TIM2->CCR1 = 85000U;

    /* 4. Configure TIM2 Channel 1 in edge-aligned PWM mode 1
     * CC1S = 00 (Channel 1 configured as output)
     * OC1M = 0110b (PWM mode 1: active while CNT < CCR1, inactive otherwise)
