    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* 2. Configure PA2 (TX) and PA3 (RX) for Alternate Function (AF7) */
    /* Set MODER2 and MODER3 to 0b10 (Alternate Function mode) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2_Msk | GPIO_MODER_MODE3_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos);

    /* Set AFRL2 and AFRL3 to AF7 (USART2_TX and USART2_RX) */
    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL2_Pos) | (0xFU << GPIO_AFRL_AFSEL3_Pos));
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos);

    /* 3. Configure USART2 frame format and baud rate */
    /* Ensure USART2 is disabled while configuring frame and baud rate */
    USART2->CR1 = 0;
    USART2->CR2 = 0; /* 1 stop bit (STOP[1:0] = 00) */
    USART2->CR3 = 0; /* No hardware flow control or DMA */

    /*
     * Baud Rate calculation:
     * Clock source: PCLK1 = 16 MHz (reset default, RCC_CCIPR USART2SEL = 00)
     * Oversampling by 16 (OVER8 = 0 in CR1, reset default)
     * BRR = f_CK / baud = 16,000,000 / 9600 = 1666.6667
     * Rounded to nearest integer: BRR = 1667 (0x0683)
     * Resulting baud rate: 16,000,000 / 1667 ≈ 9598.08 baud (error: -0.02%, well within ±2%)
     */
    USART2->BRR = 1667;

    /* 4. Enable Transmitter (TE), Receiver (RE), and USART (UE) */
    /* 8 data bits (M1=0, M0=0) and parity disabled (PCE=0) remain at 0 */
    USART2->CR1 |= USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    while (1) {
        /* Main loop */
    }
}
