#include "stm32g4xx.h"

int main(void) {
    /* 1. Enable power interface clock (PWREN) to access PWR registers */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Divide system clock by 2 via AHB prescaler before switching to high frequency (>80 MHz/150 MHz)
     *    as recommended in RM0440 Section 6.1.5 (p.233) and Section 7.2.7 (p.279). */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* 3. Enable Range 1 Boost Mode:
     *    Reset R1MODE bit in PWR_CR5 (0 = Boost mode enabled for SYSCLK up to 170 MHz, RM0440 p.267). */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 4. Configure Flash memory wait states:
     *    According to RM0440 Table 9 (p.98), in Range 1 Boost mode, 136 MHz < HCLK <= 170 MHz requires 4 WS (LATENCY = 4). */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* 5. Start HSE oscillator and wait for HSERDY */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* 6. Configure Main PLL:
     *    - Source: HSE (8 MHz)
     *    - PLLM = 1 (bits: 0b0000 = 0 -> /1) -> f_VCO_IN = 8 MHz / 1 = 8 MHz (valid: 2.66 to 16 MHz, STM32G474_Datasheet p.123)
     *    - PLLN = 42 -> f_VCO = 8 MHz * 42 = 336 MHz (valid: 96 to 344 MHz in Range 1, STM32G474_Datasheet p.123)
     *    - PLLR = 2 (bits: 0b00 = 0 -> /2) -> f_PLL_R = 336 MHz / 2 = 168 MHz (accurate to 0.0 %)
     *    - Enable PLL "R" output clock by setting PLLREN
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE
                 | (0 << RCC_PLLCFGR_PLLM_Pos)
                 | (42 << RCC_PLLCFGR_PLLN_Pos)
                 | (0 << RCC_PLLCFGR_PLLR_Pos)
                 | RCC_PLLCFGR_PLLREN;

    /* 7. Enable PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* 8. Switch system clock source to PLL and wait for status flag SWS == PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

