     *    According to RM0440 Table 9 (p.98), in Range 1 Boost mode, 136 MHz < HCLK <= 170 MHz requires 4 WS (LATENCY = 4). */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
