#include "stm32g4xx.h"

void i2c3_master_init(void)
{
    /* 1. Enable peripheral clock for GPIOC (AHB2) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;

    /* 2. Configure I2C3 kernel clock source: select HSI16 (16 MHz) in RCC_CCIPR */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos); /* 10b: HSI16 clock selected as I2C3 clock */

    /* 3. Enable I2C3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 4. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) as AF8, Open-Drain */
    /* PC8 */
    GPIOC->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE8_Pos);        /* Alternate Function mode (10b) */
    GPIOC->OTYPER |= GPIO_OTYPER_OT8;                     /* Open-drain output */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);   /* Very high speed */
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;                /* No internal pull-up (external pull-ups) */
    GPIOC->AFR[1] &= ~(0xFU << ((8U - 8U) * 4U));
    GPIOC->AFR[1] |= (8U << ((8U - 8U) * 4U));            /* AF8 = I2C3_SCL */

    /* PC9 */
    GPIOC->MODER &= ~GPIO_MODER_MODE9_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE9_Pos);        /* Alternate Function mode (10b) */
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;                     /* Open-drain output */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);   /* Very high speed */
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD9_Msk;                /* No internal pull-up (external pull-ups) */
    GPIOC->AFR[1] &= ~(0xFU << ((9U - 8U) * 4U));
    GPIOC->AFR[1] |= (8U << ((9U - 8U) * 4U));            /* AF8 = I2C3_SDA */

    /* 5. Ensure I2C3 is disabled before programming timing parameters (PE = 0) */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* 6. Program I2C3_TIMINGR for 100 kHz standard mode using HSI16 (16 MHz) clock
     * Settings from RM0440 Table 360:
     * PRESC  = 0x3
     * SCLDEL = 0x4
     * SDADEL = 0x2
     * SCLH   = 0xC3
     * SCLL   = 0xC7
     */
    I2C3->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)   |
                    (4U << I2C_TIMINGR_SCLDEL_Pos)  |
                    (2U << I2C_TIMINGR_SDADEL_Pos)  |
                    (0xC3U << I2C_TIMINGR_SCLH_Pos) |
                    (0xC7U << I2C_TIMINGR_SCLL_Pos);

    /* 7. Enable the I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
