#include "stm32g4xx.h"

void clock_init_170mhz(void)
{
    /* 1. Enable the Power Controller (PWR) interface clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Switch main regulator to Range 1 Boost mode (required for SYSCLK > 150 MHz)
     *    Clearing PWR_CR5_R1MODE puts the regulator into Boost mode.
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Configure Flash memory access latency to 4 wait states (5 CPU cycles)
     *    Required for Range 1 Boost mode with HCLK = 170 MHz (RM0440 Table 9 / Table 19).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency configuration to take effect */
    }

    /* 4. Configure the Main PLL:
     *    Source: HSI16 (16 MHz) (PLLSRC = 10b)
     *    PLLM = 4 (value 3 in register) -> VCO input = 16 MHz / 4 = 4 MHz (valid: 2.66 - 16 MHz)
     *    PLLN = 85 -> VCO output = 4 MHz * 85 = 340 MHz (valid: 96 - 344 MHz in Range 1)
     *    PLLR = 2 (value 00b in register) -> PLLCLK = 340 MHz / 2 = 170 MHz
     *    PLLREN = 1 -> Enable PLL 'R' clock output (system clock path)
     */
    RCC->PLLCFGR = (2U << RCC_PLLCFGR_PLLSRC_Pos)       |
                   (3U << RCC_PLLCFGR_PLLM_Pos)         |
                   (85U << RCC_PLLCFGR_PLLN_Pos)        |
                   (0U << RCC_PLLCFGR_PLLR_Pos)         |
                   RCC_PLLCFGR_PLLREN;

    /* 5. Enable the Main PLL */
    RCC->CR |= RCC_CR_PLLON;

    /* Busy-wait until PLL is locked */
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
    }

    /* 6. Perform the recommended clock switch transition (RM0440 §6.1.5 & §7.2.7):
     *    When switching SYSCLK to PLL with HCLK > 80 MHz / SYSCLK > 150 MHz,
     *    divide HCLK by 2 using AHB prescaler first.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;

    /* 7. Switch SYSCLK to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;

    /* Busy-wait until the PLL is used as the system clock source */
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL) {
    }

    /* Wait at least 1 µs before restoring AHB prescaler */
    for (volatile uint32_t i = 0; i < 100; i++) {
        __NOP();
    }

    /* 8. Restore AHB prescaler to /1 -> SYSCLK = HCLK = PCLK1 = PCLK2 = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV1;
}
