### Bare-Metal CMSIS C Code

```c
#include "stm32g4xx.h"

void tim3_ch1_pwm_init(void)
{
    /* 1. Enable peripheral clocks for GPIOA (AHB2) and TIM3 (APB1) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* 2. Configure PA6 as Alternate Function AF2 (TIM3_CH1) */
    /* Set MODER to Alternate Function mode (0b10) for PA6 */
    GPIOA->MODER &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER |=  (2U << GPIO_MODER_MODE6_Pos);

    /* Output type: Push-Pull */
    GPIOA->OTYPER &= ~GPIO_OTYPER_OT6;

    /* High speed */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos);

    /* No pull-up / pull-down */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD6_Msk;

    /* Select AF2 for PA6 in AFRL */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |=  (2U << GPIO_AFRL_AFSEL6_Pos);

    /* 3. Configure TIM3 time base for 1 kHz */
    TIM3->PSC = 3U;
    TIM3->ARR = 42499U;
    TIM3->CCR1 = 21250U;

    /* 4. Configure Channel 1 for Edge-aligned PWM Mode 1:
     * - CC1S = 00: CC1 channel configured as output
     * - OC1M = 0110: PWM mode 1 (active while CNT < CCR1, inactive otherwise)
     * - OC1PE = 1: Output compare 1 preload enable
     */
    TIM3->CCMR1 &= ~TIM_CCMR1_CC1S_Msk;
    TIM3->CCMR1 |=  (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Configure output polarity and enable output:
     * - CC1P = 0: Active-high output
     * - CC1E = 1: Enable OC1 output on PA6
     */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |=  TIM_CCER_CC1E;

    /* 6. Enable auto-reload preload (ARPE) and trigger an update event to load registers */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR = TIM_EGR_UG;

    /* 7. Start the counter */
    TIM3->CR1 |= TIM_CR1_CEN;
}
```

