### Complete STM32G474 Initialization Program

Below is the complete C program combining the initialization of **USART1** (115200 baud, 8N1, TX on PA9, RX on PA10) and **TIM3 Channel 1** (1 kHz, 50% duty cycle PWM on PA6) as requested.

```c
#include "stm32g4xx.h"

int main(void)
{
    /* -------------------------------------------------------------------------
     * 1. Enable Peripheral Clocks
     * -------------------------------------------------------------------------
     * - GPIOA on AHB2 bus
     * - TIM3 on APB1 bus (APB1ENR1)
     * - USART1 on APB2 bus (APB2ENR)
     */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;
    RCC->APB2ENR  |= RCC_APB2ENR_USART1EN;

    /* -------------------------------------------------------------------------
     * 2. Configure GPIOA Pins
     * -------------------------------------------------------------------------
     * - PA6:  TIM3_CH1  -> Alternate Function AF2
     * - PA9:  USART1_TX -> Alternate Function AF7
     * - PA10: USART1_RX -> Alternate Function AF7
     *
     * Note: On STM32G474, pins PA2/PA3 do not connect to USART1 in hardware;
     *       they connect to USART2/LPUART1. USART1 TX and RX on Port A map to
     *       PA9 and PA10.
     */
    /* Set MODER to Alternate Function mode (0b10) for PA6, PA9, and PA10 */
    GPIOA->MODER &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |=  (2U << GPIO_MODER_MODE6_Pos) |
                     (2U << GPIO_MODER_MODE9_Pos) |
                     (2U << GPIO_MODER_MODE10_Pos);

    /* Output type: Push-Pull on PA6 and PA9 (OTYPER = 0) */
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT6 | GPIO_OTYPER_OT9);

    /* Output speed: Very High Speed (0b11) on PA6, PA9, and PA10 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED9_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED10_Pos);

    /* Pull-up / Pull-down: Pull-up on PA10 (RX) to keep the line idle high */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD6_Msk | GPIO_PUPDR_PUPD9_Msk | GPIO_PUPDR_PUPD10_Msk);
    GPIOA->PUPDR |=  (1U << GPIO_PUPDR_PUPD10_Pos);

    /* Connect PA6 to AF2 (TIM3_CH1) via AFRL (bits 27:24) */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |=  (2U << GPIO_AFRL_AFSEL6_Pos);

    /* Connect PA9 and PA10 to AF7 (USART1) via AFRH (bits 7:4 and 11:8) */
    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL9_Msk | GPIO_AFRH_AFSEL10_Msk);
    GPIOA->AFR[1] |=  (7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* -------------------------------------------------------------------------
     * 3. Configure USART1 (115200 baud, 8N1, 16x oversampling)
     * -------------------------------------------------------------------------
     * - Disable USART before setup (UE = 0)
     * - Data format: 8 data bits (M1:M0 = 00), no parity (PCE = 0), 1 stop bit (STOP = 00)
     * - Oversampling by 16 (OVER8 = 0)
     * - Baud rate: with PCLK2 = 170 MHz, BRR = 170,000,000 / 115,200 = 1476 (0x05C4)
     * - BRR is written before enabling the USART (UE = 1)
     */
    USART1->CR1 = 0;
    USART1->CR2 = 0;
    USART1->CR3 = 0;

    USART1->BRR = 1476U;

    /* Enable Transmitter (TE), Receiver (RE), and USART peripheral (UE) */
    USART1->CR1 |= USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* Wait until transmitter and receiver are acknowledged as ready */
    while ((USART1->ISR & (USART_ISR_TEACK | USART_ISR_REACK)) != (USART_ISR_TEACK | USART_ISR_REACK))
    {
    }

    /* -------------------------------------------------------------------------
     * 4. Configure TIM3 Channel 1 (1 kHz PWM, 50% duty cycle on PA6)
     * -------------------------------------------------------------------------
     * - Timer clock: APB1 timer clock = 170 MHz
     * - Target frequency: 1000 Hz
     *   f_PWM = f_TIM / ((PSC + 1) * (ARR + 1))
     *   PSC = 3, ARR = 42499 -> 170,000,000 / (4 * 42,500) = 1000 Hz (0% error)
     * - Duty cycle: 50% -> CCR1 = 42500 / 2 = 21250 (0% error)
     */
    TIM3->PSC  = 3U;
    TIM3->ARR  = 42499U;
    TIM3->CCR1 = 21250U;

    /* Channel 1 Output Compare Mode:
     * - CC1S = 00: Output
     * - OC1M = 0110: PWM mode 1 (active while CNT < CCR1)
     * - OC1PE = 1: Preload register enable
     */
    TIM3->CCMR1 &= ~TIM_CCMR1_CC1S_Msk;
    TIM3->CCMR1 |=  (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Output polarity & Enable:
     * - CC1P = 0: Active-high output
     * - CC1E = 1: Output enabled to pin
     */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |=  TIM_CCER_CC1E;

    /* Enable Auto-reload preload (ARPE) and issue an Update Generation (UG) event */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR  = TIM_EGR_UG;

    /* Start the timer counter */
    TIM3->CR1 |= TIM_CR1_CEN;

    /* -------------------------------------------------------------------------
     * 5. Infinite Loop
     * -------------------------------------------------------------------------
     */
    while (1)
    {
        /* System running: USART1 console ready, TIM3 driving 1 kHz 50% PWM */
    }

    return 0;
}
